import { useEffect, useState } from 'react';
import Lenis from 'lenis';
import '@/App.css';
import { Toaster } from '@/components/ui/sonner';
import { Navbar } from '@/components/portfolio/Navbar';
import { Hero } from '@/components/portfolio/Hero';
import { Marquee } from '@/components/portfolio/Marquee';
import { Films } from '@/components/portfolio/Films';
import { About } from '@/components/portfolio/About';
import { Stats } from '@/components/portfolio/Stats';
import { Services } from '@/components/portfolio/Services';
import { Testimonials } from '@/components/portfolio/Testimonials';
import { Contact } from '@/components/portfolio/Contact';
import { Footer } from '@/components/portfolio/Footer';
import { VideoModal } from '@/components/portfolio/VideoModal';
import { films } from '@/data/films';

function App() {
  const [activeFilm, setActiveFilm] = useState(null);

  useEffect(() => {
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduce) return;
    const lenis = new Lenis({ lerp: 0.09, wheelMultiplier: 1 });
    let raf;
    const loop = (t) => {
      lenis.raf(t);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);

    const onAnchor = (e) => {
      const a = e.target.closest('a[href^="#"]');
      if (!a) return;
      const el = document.querySelector(a.getAttribute('href'));
      if (el) {
        e.preventDefault();
        lenis.scrollTo(el, { offset: -20 });
      }
    };
    document.addEventListener('click', onAnchor);
    return () => {
      cancelAnimationFrame(raf);
      document.removeEventListener('click', onAnchor);
      lenis.destroy();
    };
  }, []);

  return (
    <div className="relative bg-[#050505] text-[#F5F5F5] min-h-screen">
      <div className="grain-overlay" aria-hidden="true" />
      <Navbar />
      <main>
        <Hero onWatchReel={() => setActiveFilm(films[0])} />
        <Marquee />
        <Films onOpen={setActiveFilm} />
        <Stats />
        <About />
        <Services />
        <Testimonials />
        <Contact />
      </main>
      <Footer />
      <VideoModal film={activeFilm} onClose={() => setActiveFilm(null)} />
      <Toaster position="bottom-right" theme="dark" />
    </div>
  );
}

export default App;
